apiVersion: apps/v1
kind: Deployment
metadata:
  name: {{ include "n8n-sandbox-service.apiName" . }}
  labels:
    {{- include "n8n-sandbox-service.labels" . | nindent 4 }}
    app.kubernetes.io/component: api
spec:
  {{- if not .Values.api.autoscaling.enabled }}
  replicas: {{ .Values.api.replicaCount }}
  {{- end }}
  selector:
    matchLabels:
      {{- include "n8n-sandbox-service.selectorLabels" (dict "Release" .Release "Chart" .Chart "Values" .Values "component" "api") | nindent 6 }}
  template:
    metadata:
      labels:
        {{- include "n8n-sandbox-service.selectorLabels" (dict "Release" .Release "Chart" .Chart "Values" .Values "component" "api") | nindent 8 }}
      {{- with .Values.podAnnotations }}
      annotations:
        {{- toYaml . | nindent 8 }}
      {{- end }}
    spec:
      {{- with .Values.api.podSecurityContext }}
      securityContext:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      {{- with .Values.imagePullSecrets }}
      imagePullSecrets:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      containers:
        - name: api
          image: "{{ .Values.api.image.repository }}:{{ .Values.api.image.tag | default .Chart.AppVersion }}"
          imagePullPolicy: {{ .Values.api.image.pullPolicy }}
          ports:
            - name: http
              containerPort: 8080
            - name: grpc
              containerPort: 9090
            {{- with (include "n8n-sandbox-service.apiMetricsPort" .) }}
            - name: metrics
              containerPort: {{ . }}
            {{- end }}
          envFrom:
            - configMapRef:
                name: {{ include "n8n-sandbox-service.apiName" . }}-config
          env:
            - name: SANDBOX_API_KEYS
              valueFrom:
                secretKeyRef:
                  name: {{ include "n8n-sandbox-service.authSecretName" . }}
                  key: {{ .Values.auth.secretKeys.apiKeys }}
            # optional: the Secret may predate provisioner keys; the API treats
            # an unset variable as "no provisioner keys".
            - name: SANDBOX_API_PROVISIONER_KEYS
              valueFrom:
                secretKeyRef:
                  name: {{ include "n8n-sandbox-service.authSecretName" . }}
                  key: {{ .Values.auth.secretKeys.provisionerKeys }}
                  optional: true
            - name: SANDBOX_API_SCALER_KEYS
